  \draw[choice focus] (a) -- node[choice label,sloped] {$2\to B$} (ab);

  \node[state focus,label={[membership]above left:$A=\{1,3\},\ B=\{2\}$}] (aba) at (-1.75,2.45) {$F$\\$(4,4,2)$};
  \node[state muted,label={[membership]above right:$A=\{1\},\ B=\{2,3\}$}] (abb) at (1.25,2.45) {$F$\\$(4,1,5)$};
  \draw[choice focus] (ab) -- node[choice label,sloped] {$3\to A$} (aba);
  \draw[choice muted] (ab) -- node[choice label muted,sloped] {$3\to B$} (abb);

  \node[explain box] at (0,-.05) {The names $A$ and $B$ stay fixed.\\Their sums may change order without changing either parameter's identity.};
\end{tikzpicture}
\end{center}

\begin{center}
\begin{tikzpicture}[x=1cm,y=.78cm]
  \path[use as bounding box] (-4.2,-.60) rectangle (4.2,13.25);
  \node[state start,label={[membership]above:$L=\varnothing,\ S=\varnothing$}] (r) at (0,12.05) {$G$\\$(1,0,0)$};
  \node[state focus,label={[membership]above left:$L=\{1\},\ S=\varnothing$}] (l) at (-2.15,9.45) {$G$\\$(2,1,0)$};
  \node[state duplicate,label={[membership]above right:$L=\{1\},\ S=\varnothing$}] (s) at (2.15,9.45) {$G$\\$(2,1,0)$};
  \draw[choice focus] (r) -- node[choice label,sloped] {$1\to L$} (l);
  \draw[choice duplicate] (r) -- node[choice label duplicate,sloped] {$1\to S$} (s);
  \draw[equivalent] (l) to[bend left=8] node[equality label] {equal arguments; two calls} (s);

  \node[state muted,label={[membership]above left:$L=\{1,2\},\ S=\varnothing$}] (ll) at (-3.20,6.10) {$G$\\$(3,3,0)$};
  \node[state focus,label={[membership]above right:$L=\{2\},\ S=\{1\}$}] (ls) at (-.65,6.10) {$G$\\$(3,2,1)$};
  \draw[choice muted] (l) -- node[choice label muted,sloped] {$2\to L$} (ll);
  \draw[choice focus] (l) -- node[choice label,sloped] {$2\to S$} (ls);
  \node[swap note] at (2.72,6.20) {raw $(1,2)$\\$\Downarrow$ normalize\\$L\leftrightarrow S$};

  \node[state muted,label={[membership]above left:$L=\{2,3\},\ S=\{1\}$}] (lsl) at (-1.70,2.65) {$G$\\$(4,5,1)$};
  \node[state focus,label={[membership]above right:$L=\{1,3\},\ S=\{2\}$}] (lss) at (1.40,2.65) {$G$\\$(4,4,2)$};
  \draw[choice muted] (ls) -- node[choice label muted,sloped] {$3\to L$} (lsl);
  \draw[choice focus] (ls) -- node[choice label,sloped] {$3\to S$} (lss);
  \node[swap note] at (3.08,2.38) {raw $(2,4)$\\$\Downarrow$ normalize\\$L\leftrightarrow S$};

  \node[explain box] at (0,-.05) {$L$ and $S$ mean larger and smaller \emph{now}.\\Elements never move; only the coordinate roles are re-sorted.};
\end{tikzpicture}
\end{center}

\begin{center}
\begin{tikzpicture}[x=1cm,y=.70cm]
  \path[use as bounding box] (-4.2,-2.00) rectangle (4.2,13.30);
  \node[state start,label={[membership]above:$C=\varnothing,\ O=\varnothing$}] (r) at (0,12.10) {$H$\\$(1,0,0)$};
  \node[state focus,label={[membership]above left:$C=\{1\},\ O=\varnothing$}] (c) at (-2.15,9.50) {$H$\\$(2,1,0)$};
  \node[state duplicate,label={[membership]above right:$C=\{1\},\ O=\varnothing$}] (o) at (2.15,9.50) {$H$\\$(2,1,0)$};
  \draw[choice focus] (r) -- node[choice label,sloped] {$1\to C$} (c);
  \draw[choice duplicate] (r) -- node[choice label duplicate,sloped] {$1\to O$} (o);
  \draw[equivalent] (c) to[bend left=8] node[equality label] {equal arguments; two calls} (o);

  \node[state muted,label={[membership]above left:$C=\{1,2\},\ O=\varnothing$}] (cc) at (-3.20,6.15) {$H$\\$(3,3,0)$};
  \node[state focus,label={[membership]above right:$C=\{2\},\ O=\{1\}$}] (co) at (-.65,6.15) {$H$\\$(3,2,1)$};
  \draw[choice muted] (c) -- node[choice label muted,sloped] {$2\to C$} (cc);
  \draw[choice focus] (c) -- node[choice label,sloped] {$2\to O$} (co);
  \node[swap note] at (2.55,6.10) {call $(O+2,C)$\\recipient becomes $C$};

  \node[state muted,label={[membership]above left:$C=\{2,3\},\ O=\{1\}$}] (coc) at (-1.75,2.80) {$H$\\$(4,5,1)$};
  \node[state focus,label={[membership]above right:$C=\{1,3\},\ O=\{2\}$}] (coo) at (1.35,2.80) {$H$\\$(4,4,2)$};
  \draw[choice muted] (co) -- node[choice label muted,sloped] {$3\to C$} (coc);
  \draw[choice focus] (co) -- node[choice label,sloped] {$3\to O$} (coo);

  \node[state contrast,label={[membership]above left:$C=\{1,2,3\},\ O=\varnothing$}] (wide) at (-2.15,-.55) {$H$\\$(4,6,0)$};
  \node[state contrast,label={[membership]above right:$C=\{4\},\ O=\{1,2,3\}$}] (small) at (2.15,-.55) {$H$\\$(5,4,6)$};
  \draw[contrast edge] (wide) -- node[contrast label] {$4\to O$} (small);
  \node[contrast note] at (0,-1.78) {$C<O$ is valid: roles follow the last ``other'' action, not numerical size.};
\end{tikzpicture}
\end{center}

{\sffamily\fontsize{6.7}{7.55}\selectfont
Along history $\mathcal H$, the physical assignment is always
$A=\{1,3\}$ and $B=\{2\}$. The diagrams differ only in how the current call
names these sets.
\par\vspace{2mm}
\begin{center}
\renewcommand{\arraystretch}{1.35}
\begin{tabular}{>{\bfseries}p{16mm}p{37mm}p{48mm}p{52mm}}
Form & final key & first coordinate means & why a role changes\\\hline
$F$ & $(4,4,2)$ & permanently named $A$ & never changes\\
$G$ & $(4,4,2)$ & currently larger set & normalize whenever order reverses\\
$H$ & $(4,4,2)$ & recipient designated current & choosing other rotates roles\\
\end{tabular}
\end{center}
\par\vspace{2mm}
The equal numeric keys at the end of this one history do not make the
formulations identical. History $\mathcal K$ separates them immediately:
$F(5,6,4)$, $G(5,6,4)$, but $H(5,4,6)$ with $C<O$.
\par\vspace{2mm}
Repeated calls are deliberately drawn twice. The dotted equality annotation
means ``same arguments and two additive contributions,'' not a cache lookup or
a merged memoization node.}

